            label: `${m.id === currentModelId ? '$(check) ' : '$(sparkle) '}${m.name || m.id}`,
            description: `${m.vendor} / ${m.family}${m.id === currentModelId ? '  (当前)' : ''}`,
            detail: `API 版本: ${m.version}`,
